// Package calendar is the XNYS exchange calendar shared by Go services (rule MD-005, DF-011,
// ADR-0020). Sessions come from xnys_sessions.csv, generated by scripts/gen_calendar.py from
// exchange_calendars and embedded here; Python reads the identical file (tbcore.data.calendar).
// All times are UTC; exchange-local dates are derived from the table, so DST is handled once.
package calendar

import (
	"bufio"
	"bytes"
	_ "embed"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

//go:embed xnys_sessions.csv
var xnysCSV []byte

// Session is one trading day.
type Session struct {
	Date       string // exchange-local YYYY-MM-DD
	PreOpen    time.Time
	Open       time.Time
	Close      time.Time
	PostClose  time.Time
	EarlyClose bool
}

// Calendar is an immutable session table.
type Calendar struct {
	sessions []Session
	byDate   map[string]int
}

var (
	once sync.Once
	xnys *Calendar
	err0 error
)

// XNYS returns the embedded NYSE calendar.
func XNYS() *Calendar {
	once.Do(func() { xnys, err0 = Parse(xnysCSV) })
	if err0 != nil {
		panic(fmt.Sprintf("calendar: embedded table invalid: %v", err0))
	}
	return xnys
}

// Parse reads a session table.
func Parse(b []byte) (*Calendar, error) {
	c := &Calendar{byDate: map[string]int{}}
	sc := bufio.NewScanner(bytes.NewReader(b))
	line := 0
	for sc.Scan() {
		line++
		if line == 1 {
			continue
		}
		f := strings.Split(sc.Text(), ",")
		if len(f) != 6 {
			return nil, fmt.Errorf("line %d: %d fields", line, len(f))
		}
		var ts [4]time.Time
		for i := range 4 {
			t, err := time.Parse(time.RFC3339, f[i+1])
			if err != nil {
				return nil, fmt.Errorf("line %d: %w", line, err)
			}
			ts[i] = t.UTC()
		}
		s := Session{Date: f[0], PreOpen: ts[0], Open: ts[1], Close: ts[2], PostClose: ts[3], EarlyClose: f[5] == "1"}
		if len(c.sessions) > 0 && !s.Open.After(c.sessions[len(c.sessions)-1].Open) {
			return nil, fmt.Errorf("line %d: sessions not increasing", line)
		}
		c.byDate[s.Date] = len(c.sessions)
		c.sessions = append(c.sessions, s)
	}
	if len(c.sessions) == 0 {
		return nil, fmt.Errorf("empty calendar")
	}
	return c, sc.Err()
}

// First and Last bound the table.
func (c *Calendar) First() Session { return c.sessions[0] }
func (c *Calendar) Last() Session  { return c.sessions[len(c.sessions)-1] }

// Session returns the session for an exchange-local date.
func (c *Calendar) Session(date string) (Session, bool) {
	i, ok := c.byDate[date]
	if !ok {
		return Session{}, false
	}
	return c.sessions[i], true
}

// Sessions returns sessions whose regular open is in [from, to).
func (c *Calendar) Sessions(from, to time.Time) []Session {
	i := sort.Search(len(c.sessions), func(i int) bool { return !c.sessions[i].Open.Before(from) })
	var out []Session
	for ; i < len(c.sessions) && c.sessions[i].Open.Before(to); i++ {
		out = append(out, c.sessions[i])
	}
	return out
}

// containing returns the session whose [PreOpen, PostClose) contains t, if any.
func (c *Calendar) containing(t time.Time) (Session, bool) {
	i := sort.Search(len(c.sessions), func(i int) bool { return c.sessions[i].PostClose.After(t) })
	if i < len(c.sessions) && !t.Before(c.sessions[i].PreOpen) {
		return c.sessions[i], true
	}
	return Session{}, false
}

// SessionAt returns the session containing t (extended hours included) and the session part.
func (c *Calendar) SessionAt(t time.Time) (Session, Part, bool) {
	s, ok := c.containing(t)
	if !ok {
		return Session{}, PartClosed, false
	}
	switch {
	case t.Before(s.Open):
		return s, PartPre, true
	case t.Before(s.Close):
		return s, PartRegular, true
	default:
		return s, PartPost, true
	}
}

// Part of a session.
type Part int

const (
	PartClosed Part = iota
	PartPre
	PartRegular
	PartPost
)

func (p Part) String() string {
	return [...]string{"closed", "pre", "regular", "post"}[p]
}

// IsOpen reports whether the regular session is open at t.
func (c *Calendar) IsOpen(t time.Time) bool {
	_, p, ok := c.SessionAt(t)
	return ok && p == PartRegular
}

// NextOpen returns the first regular open strictly after t.
func (c *Calendar) NextOpen(t time.Time) (time.Time, bool) {
	i := sort.Search(len(c.sessions), func(i int) bool { return c.sessions[i].Open.After(t) })
	if i == len(c.sessions) {
		return time.Time{}, false
	}
	return c.sessions[i].Open, true
}

// PreviousSession returns the last session whose regular close is at or before t.
func (c *Calendar) PreviousSession(t time.Time) (Session, bool) {
	i := sort.Search(len(c.sessions), func(i int) bool { return c.sessions[i].Close.After(t) })
	if i == 0 {
		return Session{}, false
	}
	return c.sessions[i-1], true
}

// BarOpens returns the expected bar open times of width d in a session (MD-004): bars are aligned to
// the session start and never cross the session boundary; a final shorter bar is not produced (it is
// truncated at the close). extended includes pre and post market.
func (s Session) BarOpens(d time.Duration, extended bool) []time.Time {
	start, end := s.Open, s.Close
	if extended {
		start, end = s.PreOpen, s.PostClose
	}
	var out []time.Time
	for t := start; t.Before(end); t = t.Add(d) {
		out = append(out, t)
	}
	return out
}

// BarClose returns the close of the bar opened at open with width d, truncated at the session
// part's end (half days end bars at the early close).
func (s Session) BarClose(open time.Time, d time.Duration) time.Time {
	end := open.Add(d)
	switch {
	case open.Before(s.Open) && end.After(s.Open):
		return s.Open
	case open.Before(s.Close) && end.After(s.Close):
		return s.Close
	case end.After(s.PostClose):
		return s.PostClose
	}
	return end
}
